+    this.#panel = panel;
+    this.#searchInput = searchInput;
+    this.#list = list;
+    this.#noResults = noResults;
+    if (itemSelector) this.#itemSelector = itemSelector;
+  }
+
+  populate(items) {
+    this.#items = items;
+    this.#list.innerHTML = "";
