+      this.#searchInput?.focus();
+      this.#searchInput?.select?.();
+      onShown?.();
+    };
+    this.#panel.addEventListener("popupshown", onPanelShown);
+
+    const onPanelHidden = event => {
+      if (event.target !== this.#panel) return;
+      if (this.#searchInput) {
