+
+// static
+void ZenGlobalShortcuts::NativeUnregister(Registration& aReg) {
+  MacGlobalShortcuts::Unregister(aReg);
+}
+
+// static
+void ZenGlobalShortcuts::NativeShutdown() { MacGlobalShortcuts::Shutdown(); }
+
+}  // namespace zen

